<section id="cash-view" hidden aria-labelledby="cash-title">
    <div class="section-heading"><div><h1 id="cash-title">Caja</h1><p>Abre tu turno, registra el efectivo y realiza el corte al terminar.</p></div><div class="form-actions catalog-actions"><button id="cash-manage" data-icon="pen-to-square" type="button" class="secondary" hidden>Configurar cajas</button><button id="cash-own" data-icon="wallet" type="button" class="secondary" hidden>Continuar mi turno</button><button id="cash-open" data-icon="plus" type="button" class="primary">Abrir turno</button></div></div>
    <p id="cash-message" role="status" aria-live="polite"></p>
    <div id="cash-list-panel"><div class="filters"><div><label for="cash-box-filter">Caja</label><select id="cash-box-filter"><option value="">Todas</option></select></div><div><label for="cash-status-filter">Estado del turno</label><select id="cash-status-filter"><option value="">Todos</option><option value="abierto">Abiertos</option><option value="cerrado">Cerrados</option></select></div></div><p id="cash-scope" class="hint"></p><div class="table-scroll"><table class="cash-turns-table"><thead><tr><th>Turno / apertura</th><th>Caja y ubicación</th><th>Responsable</th><th>Estado</th><th>Corte</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody id="cash-turn-rows"></tbody></table></div><p id="cash-turns-empty" hidden>No hay turnos para esta selección. Abre un turno para comenzar.</p><div class="form-actions"><button id="cash-more" type="button" class="secondary" hidden>Cargar turnos anteriores</button></div></div>
    <section id="cash-open-panel" class="catalog-editor" hidden aria-labelledby="cash-open-title"><div class="section-heading"><h2 id="cash-open-title">Abrir turno de caja</h2><button id="cash-open-back" type="button" class="secondary">Volver a turnos</button></div><form id="cash-open-form"><fieldset id="cash-open-fields" class="adjust-fields"><div class="product-fields"><div><label for="cash-open-box">Caja a utilizar</label><select id="cash-open-box" required></select><p id="cash-open-location" class="hint"></p></div><div><label for="cash-open-amount">Fondo inicial de efectivo</label><input id="cash-open-amount" type="number" min="0" max="999999999999.99" step="0.01" value="0" required><p class="hint">El dinero que dejas en el cajón para dar cambio.</p></div><div class="full-width"><label for="cash-open-note">Notas de apertura (opcional)</label><textarea id="cash-open-note" rows="3" maxlength="300"></textarea></div></div></fieldset><p id="cash-open-error" class="message" role="alert"></p><div class="form-actions"><button id="cash-open-save" data-icon="lock" type="submit" class="primary">Confirmar apertura</button><button id="cash-open-cancel" type="button" class="secondary">Cancelar</button></div></form></section>
    <section id="cash-detail-panel" class="catalog-editor" hidden aria-labelledby="cash-detail-title"><div class="section-heading"><div><h2 id="cash-detail-title"></h2><p id="cash-detail-meta" class="hint"></p></div><div class="form-actions catalog-actions"><button id="cash-detail-reload" data-icon="rotate" type="button" class="secondary">Actualizar turno</button><button id="cash-detail-back" type="button" class="secondary">Volver a turnos</button></div></div>
        <div class="cash-report"><dl><div><dt>Fondo inicial</dt><dd id="cash-report-opening"></dd></div><div><dt>Cobros de ventas en efectivo</dt><dd id="cash-report-sales"></dd></div><div><dt>Abonos de clientes en efectivo</dt><dd id="cash-report-installments"></dd></div><div><dt>Gastos ya incluidos en las salidas</dt><dd id="cash-report-expenses"></dd></div><div><dt>Pagos a proveedores desde caja</dt><dd id="cash-report-providers"></dd></div><div><dt>Reembolsos en efectivo</dt><dd id="cash-report-refunds"></dd></div><div><dt>Entradas de efectivo</dt><dd id="cash-report-in"></dd></div><div><dt>Salidas de efectivo</dt><dd id="cash-report-out"></dd></div><div class="cash-report-total"><dt>Efectivo esperado</dt><dd id="cash-report-expected"></dd></div><div id="cash-counted-field" hidden><dt>Efectivo contado al cierre</dt><dd id="cash-report-counted"></dd></div><div id="cash-difference-field" hidden><dt>Diferencia del corte</dt><dd id="cash-report-difference"></dd></div></dl><p id="cash-detail-status" class="hint"></p><p id="cash-detail-notes" class="hint"></p></div>
        <div id="cash-detail-actions" class="form-actions"><button id="cash-entry" data-icon="plus" type="button" class="secondary">Entrada de efectivo</button><button id="cash-exit" data-icon="money-bill-transfer" type="button" class="secondary">Salida de efectivo</button><button id="cash-close" data-icon="lock" type="button" class="primary">Cerrar turno y hacer corte</button></div>
        <section id="cash-action-panel" class="cash-action" hidden aria-labelledby="cash-action-title"><h3 id="cash-action-title"></h3><p id="cash-action-help" class="hint"></p><form id="cash-action-form"><fieldset id="cash-action-fields" class="adjust-fields"><div class="product-fields"><div><label for="cash-action-amount" id="cash-action-amount-label">Monto</label><input id="cash-action-amount" type="number" min="0.01" max="999999999999.99" step="0.01" required></div><div><label for="cash-action-note" id="cash-action-note-label">Motivo</label><textarea id="cash-action-note" rows="2" maxlength="200" required></textarea></div></div><p id="cash-action-preview" class="hint" aria-live="polite"></p><label id="cash-close-confirm-field" class="check-label" hidden><input id="cash-close-confirm" type="checkbox"> Confirmo que conté el efectivo y quiero cerrar este turno.</label></fieldset><p id="cash-action-error" class="message" role="alert"></p><div class="form-actions"><button id="cash-action-save" data-icon="check" type="submit" class="primary">Registrar</button><button id="cash-action-cancel" type="button" class="secondary">Cancelar</button></div></form></section>
        <h3 class="cash-ledger-title">Entradas y salidas fuera de ventas</h3><div class="table-scroll"><table class="cash-movements-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Monto</th><th>Usuario</th><th>Motivo</th></tr></thead><tbody id="cash-movement-rows"></tbody></table></div><p id="cash-movements-empty" hidden>No hay entradas ni salidas adicionales en este turno.</p>
    </section>
    <section id="cash-config-panel" class="catalog-editor" hidden aria-labelledby="cash-config-title"><div class="section-heading"><h2 id="cash-config-title">Configurar cajas</h2><button id="cash-config-back" type="button" class="secondary">Volver a turnos</button></div><div class="category-layout"><div class="table-scroll"><table><thead><tr><th>Caja / ubicación</th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody id="cash-config-rows"></tbody></table></div><form id="cash-config-form"><fieldset id="cash-config-fields" class="adjust-fields"><h3 id="cash-config-editor-title">Crear caja</h3><label for="cash-config-name">Nombre de la caja</label><input id="cash-config-name" name="nombre" maxlength="100" required placeholder="Ej. Caja 2"><label for="cash-config-location">Ubicación de venta</label><select id="cash-config-location" name="ubicacion_id" required></select><label for="cash-config-active">Estado</label><select id="cash-config-active" name="activo"><option value="1">Activa</option><option value="0">Inactiva</option></select><p class="hint">Las cajas operan en ubicaciones habilitadas para venta. Cierra el turno antes de cambiar la ubicación o desactivar la caja.</p></fieldset><p id="cash-config-error" class="message" role="alert"></p><div class="form-actions"><button id="cash-config-save" data-icon="floppy-disk" type="submit" class="primary">Guardar caja</button><button id="cash-config-new" type="button" class="secondary">Nueva</button></div></form></div></section>
</section>
